#!/usr/bin/env python3
"""读取 CSV 文件，统计每一列的非空值数量。"""

import argparse
import csv
import sys
from collections import Counter


def is_empty(value):
    return value is None or value.strip() == ""


def count_nonempty(path):
    counts = Counter()
    with open(path, newline="", encoding="utf-8-sig") as f:
        reader = csv.reader(f)
        try:
            header = next(reader)
        except StopIteration:
            return header_counts_empty()

        cols = list(range(len(header)))
        for row in reader:
            for i in cols:
                if i < len(row) and not is_empty(row[i]):
                    counts[i] += 1

    return [(header[i], counts[i]) for i in cols]


def header_counts_empty():
    return []


def main():
    parser = argparse.ArgumentParser(description="统计 CSV 每一列的非空值数量")
    parser.add_argument("csv_file", help="CSV 文件路径")
    parser.add_argument("--sep", default=",", help="列分隔符，默认逗号")
    args = parser.parse_args()

    try:
        result = count_nonempty(args.csv_file)
    except FileNotFoundError:
        sys.exit(f"错误：文件不存在 {args.csv_file}")
    except csv.Error as e:
        sys.exit(f"错误：CSV 解析失败 {e}")

    if not result:
        print("文件为空或没有表头。")
        return

    width = max(len(name) for name, _ in result)
    for name, count in result:
        print(f"{name.ljust(width)}\t{count}")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""读取 CSV 文件，统计每一列的非空值数量。"""

import argparse
import csv
import sys
from collections import Counter


def is_empty(value):
    return value is None or value.strip() == ""


def count_nonempty(path, sep=","):
    counts = Counter()
    with open(path, newline="", encoding="utf-8-sig") as f:
        reader = csv.reader(f, delimiter=sep)
        try:
            header = next(reader)
        except StopIteration:
            return []

        for row in reader:
            for i in range(len(header)):
                if i < len(row) and not is_empty(row[i]):
                    counts[i] += 1

    return [(header[i], counts[i]) for i in range(len(header))]


def main():
    parser = argparse.ArgumentParser(description="统计 CSV 每一列的非空值数量")
    parser.add_argument("csv_file", help="CSV 文件路径")
    parser.add_argument("--sep", default=",", help="列分隔符，默认逗号")
    args = parser.parse_args()

    try:
        result = count_nonempty(args.csv_file, args.sep)
    except FileNotFoundError:
        sys.exit(f"错误：文件不存在 {args.csv_file}")
    except csv.Error as e:
        sys.exit(f"错误：CSV 解析失败 {e}")

    if not result:
        print("文件为空或没有表头。")
        return

    width = max(len(name) for name, _ in result)
    for name, count in result:
        print(f"{name.ljust(width)}\t{count}")


if __name__ == "__main__":
    main()
